[{"order":1,"type":"heading","text":"Handling Multiple Pages, Tabs, and Popups in Playwright"},{"order":2,"type":"paragraph","text":"Modern web applications frequently open new windows, browser tabs, or authentication popups. Playwright provides a robust API to manage these contexts seamlessly without losing your test session or getting stuck in a single execution thread."},{"order":3,"type":"subheading","text":"Understanding Browser Contexts and Pages"},{"order":4,"type":"paragraph","text":"In Playwright, a Browser object can have multiple BrowserContexts, and each context can have multiple Page objects. A Page represents a single tab or window. When a link with target="_blank" is clicked, Playwright allows you to listen for and capture the newly created page."},{"order":5,"type":"subheading","text":"Handling New Tabs and Popups"},{"order":6,"type":"paragraph","text":"To handle an action that opens a new tab or popup, use the context.waitForEvent("page") method concurrently with the action that triggers the popup. This prevents race conditions where the popup opens before your test starts listening for it."},{"order":7,"type":"code","text":"const { test, chromium } = require("@playwright/test");

test("handle new tab", async ({ page }) => {
  await page.goto("https://example.com");

  // Start waiting for the new page before clicking
  const [newPage] = await Promise.all([
    page.waitForEvent("page"),
    page.click("text=Open New Tab")
  ]);

  await newPage.waitForLoadState();
  console.log(await newPage.title());

  // Perform actions on the new tab
  await newPage.close();
});"},{"order":8,"type":"subheading","text":"Working with Multiple Existing Pages"},{"order":9,"type":"paragraph","text":"If multiple pages are already open within the same browser context, you can access all of them using the context.pages() method. This returns an array of all active page instances."},{"order":10,"type":"code","text":"const allPages = page.context().pages();
console.log(`Total active pages: ${allPages.length}`);

// Iterate through pages or select a specific one
const secondPage = allPages[1];
await secondPage.bringToFront();"},{"order":11,"type":"subheading","text":"Best Practices for Multi-Page Testing"},{"order":12,"type":"bullet_point","text":"Always wait for the new page to load using await newPage.waitForLoadState() or by waiting for a specific selector."},{"order":13,"type":"bullet_point","text":"Close newly opened pages using await newPage.close() at the end of your test to free up system resources."},{"order":14,"type":"bullet_point","text":"Use Promise.all() whenever an action triggers a navigation or popup event to avoid flaky test execution."}]
